<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { mdiViewDashboardOutline, mdiMemory, mdiLan, mdiDesktopTowerMonitor, mdiHarddisk, mdiDatabaseOutline, mdiPlus, mdiMagnify, mdiArrowTopRight, mdiArrowLeft, mdiDownload, mdiUpload, mdiCheckCircleOutline, mdiAlertCircleOutline, mdiClose, mdiContentCopy, mdiTrashCanOutline, mdiCubeOutline, mdiArrowRight, mdiCogOutline, mdiRefresh, mdiCheck, mdiChevronRight, mdiServerOutline, mdiInformationOutline } from '@mdi/js';
import type { Category, Component, Configuration, Database, InventoryPC, Placement, Specs, System } from '../shared/types';
import { categories } from '../shared/types';
import { checkConfiguration } from '../shared/compatibility';
const db=ref<Database>({components:[],systems:[],configurations:[],pcs:[]});
const loading=ref(true), failure=ref(''), busy=ref(false), notice=ref(''), noticeOpen=ref(false);
const page=ref('Configurations'), search=ref(''), filter=ref('All configurations'), categoryFilter=ref('All components');
const working=ref<Configuration|null>(null), original=ref(''), detailTab=ref('components');
const componentDraft=ref<Component|null>(null), systemDraft=ref<System|null>(null), pcDraft=ref<InventoryPC|null>(null);
const jsonSpecs=ref(''), advanced=ref(false), confirmDelete=ref<{collection:string;id:string;name:string}|null>(null);
const addCategory=ref<Category>('Scientific card'), addPart=ref(''), addQty=ref(1);
const csvCollection=ref('components'), importFile=ref<File|null>(null), importing=ref(false);
const navigation=[{name:'Configurations',icon:mdiViewDashboardOutline},{name:'Component catalog',icon:mdiMemory},{name:'Equipment systems',icon:mdiLan},{name:'PC inventory',icon:mdiDesktopTowerMonitor},{name:'Storage planner',icon:mdiHarddisk}];
const uid=()=>crypto.randomUUID();
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
function toast(text:string){notice.value=text;noticeOpen.value=true;}
async function api(url:string,options:RequestInit={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');return result;}
async function load(){try{db.value=await api('/api/state');failure.value='';}catch(e){failure.value=String(e);}finally{loading.value=false;}}
async function saveRecord(collection:string,record:{id:string}){busy.value=true;try{await api(`/api/${collection}/${record.id}`,{method:'PUT',body:JSON.stringify(record)});await load();return true;}catch(e){toast(String(e));return false;}finally{busy.value=false;}}
function navigate(name:string){if(working.value&&dirty.value&&!window.confirm('Discard unsaved configuration changes?'))return;page.value=name;working.value=null;search.value='';}
const dirty=computed(()=>!!working.value&&JSON.stringify(working.value)!==original.value);
function openConfig(c:Configuration){working.value=clone(c);original.value=JSON.stringify(c);detailTab.value='components';page.value='Configurations';}
function newConfig(){const c:Configuration={id:uid(),name:'Untitled configuration',description:'',systemId:'',status:'Draft',updatedAt:new Date().toISOString(),placements:[],storage:{raid:'none',bootMirror:false},notes:''};openConfig(c);original.value='';}
function duplicate(c:Configuration){const copy=clone(c);copy.id=uid();copy.name=`${c.name} · copy`;copy.status='Draft';copy.updatedAt=new Date().toISOString();openConfig(copy);original.value='';}
async function saveConfig(){if(!working.value)return;if(working.value.status==='Approved'&&report.value?.findings.some(f=>f.severity==='error'))return toast('Resolve compatibility conflicts before marking this configuration Approved.');working.value.updatedAt=new Date().toISOString();if(await saveRecord('configurations',working.value)){original.value=JSON.stringify(working.value);toast('Configuration saved to CSV.');}}
const report=computed(()=>working.value?checkConfiguration(working.value,db.value):null);
const reports=computed(()=>Object.fromEntries(db.value.configurations.map(c=>[c.id,checkConfiguration(c,db.value)])));
const configs=computed(()=>db.value.configurations.filter(c=>(c.name+' '+c.description+' '+systemName(c.systemId)).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All configurations'||(filter.value==='Conflicts'?reports.value[c.id]?.status==='Conflicts':c.status===filter.value))));
const components=computed(()=>db.value.components.filter(c=>(c.name+' '+c.manufacturer).toLowerCase().includes(search.value.toLowerCase())&&(categoryFilter.value==='All components'||c.category===categoryFilter.value)));
const systems=computed(()=>db.value.systems.filter(s=>(s.name+' '+s.location).toLowerCase().includes(search.value.toLowerCase())));
const pcs=computed(()=>db.value.pcs.filter(p=>(p.name+' '+p.serial+' '+p.location).toLowerCase().includes(search.value.toLowerCase())));
const conflictCount=computed(()=>Object.values(reports.value).filter(r=>r.status==='Conflicts').length);
const availableParts=computed(()=>db.value.components.filter(c=>c.category===addCategory.value));
const linkedSystem=computed(()=>db.value.systems.find(s=>s.id===working.value?.systemId));
const selectedDrives=computed(()=>working.value?.placements.filter(p=>part(p.componentId)?.category==='Drive')||[]);
const selectedCards=computed(()=>working.value?.placements.filter(p=>['GPU','Scientific card','Network card','Storage adapter'].includes(part(p.componentId)?.category||''))||[]);
const slots=computed(()=>part(working.value?.placements.find(p=>part(p.componentId)?.category==='Motherboard')?.componentId||'')?.specs.slots||[]);
function part(id:string){return db.value.components.find(c=>c.id===id);}
function systemName(id:string){return db.value.systems.find(s=>s.id===id)?.name||'No equipment linked';}
function configName(id:string){return db.value.configurations.find(c=>c.id===id)?.name||'Unassigned';}
function errors(id:string){return reports.value[id]?.findings.filter(f=>f.severity==='error').length||0;}
function quantity(c:Configuration){return c.placements.reduce((n,p)=>n+p.quantity,0);}
function capacity(n:number){return n>=1000?`${+(n/1000).toFixed(2)} TB`:`${n} GB`;}
function portTotal(s:System,key:'usbA'|'usbC'|'ethernet'){return s.connections.reduce((n,c)=>n+c[key],0);}
function summary(c:Component){const s=c.specs;switch(c.category){case 'Chassis':return `${s.supportedForms?.join(' / ')||'Form unknown'} · ${s.hotSwapBays??'?'} hot-swap bays`;case 'Motherboard':return `${s.socket||'?'} · ${s.formFactor||'?'} · ${s.slots?.length??'?'} expansion slots`;case 'CPU':return `${s.socket||'Socket unknown'} · ${s.powerW??'?'} W`;case 'Memory':return `${s.capacityGb??'?'} GB · ${s.memoryType||'Type unknown'}`;case 'Drive':return `${capacity(s.capacityGb||0)} · ${s.driveInterface||'?'} · ${s.driveSize||'?'}`;case 'PSU':return `${s.capacityW??'?'} W · ${s.sataPower??'?'} SATA plugs`;case 'Cooler':return `${s.heightMm??'?'} mm · ${s.supportsSockets?.join(', ')||'Socket unknown'}`;default:return `${s.slotBus||'?'} x${s.slotWidth||'?'} · ${s.requiredLanes||'?'} lanes · ${s.lengthMm??'?'} mm`;}}
function addComponent(){if(!working.value||!addPart.value)return;working.value.placements.push({id:uid(),componentId:addPart.value,quantity:addQty.value,slotId:'',role:part(addPart.value)?.category==='Drive'?'data':'general',mount:'auto',group:''});addPart.value='';addQty.value=1;}
function removePlacement(id:string){if(working.value)working.value.placements=working.value.placements.filter(p=>p.id!==id);}
const specFields:Record<Category,{key:keyof Specs;label:string;kind?:'text'|'list'|'select'|'bool';items?:string[]}[]>={
 'Chassis':[{key:'supportedForms',label:'Supported board forms',kind:'list'},{key:'rearSlots',label:'Rear bracket positions'},{key:'maxCardLengthMm',label:'Card length clearance (mm)'},{key:'maxCardHeightMm',label:'Card height clearance (mm)'},{key:'maxCoolerHeightMm',label:'Cooler height clearance (mm)'},{key:'bays25',label:'Internal 2.5-inch bays'},{key:'bays35',label:'Internal 3.5-inch bays'},{key:'hotSwapBays',label:'Separate front hot-swap bays'},{key:'lengthMm',label:'Length (mm)'},{key:'heightMm',label:'Height (mm)'},{key:'widthMm',label:'Width (mm)'}],
 'Motherboard':[{key:'socket',label:'CPU socket',kind:'text'},{key:'formFactor',label:'Form factor',kind:'select',items:['ATX','Micro-ATX','Mini-ITX','E-ATX']},{key:'memoryType',label:'Memory type',kind:'select',items:['DDR3','DDR4','DDR5']},{key:'dimmSlots',label:'DIMM slots'},{key:'maxMemoryGb',label:'Maximum memory (GB)'},{key:'usbA',label:'Usable external USB-A ports'},{key:'usbC',label:'Usable external USB-C ports'},{key:'ethernet',label:'Ethernet ports'},{key:'sataPorts',label:'SATA ports'},{key:'m2Slots',label:'NVMe M.2 slots'},{key:'m2Lengths',label:'M.2 lengths (mm, comma separated)',kind:'list'},{key:'bifurcation',label:'PCIe bifurcation supported',kind:'bool'},{key:'powerW',label:'Estimated power (W)'}],
 'CPU':[{key:'socket',label:'CPU socket',kind:'text'},{key:'powerW',label:'Maximum power estimate (W)'}],
 'Memory':[{key:'memoryType',label:'Memory type',kind:'select',items:['DDR3','DDR4','DDR5']},{key:'capacityGb',label:'Capacity per module (GB)'},{key:'powerW',label:'Power per module (W)'}],
 'GPU':[], 'Scientific card':[], 'Network card':[], 'Storage adapter':[],
 'Drive':[{key:'capacityGb',label:'Capacity per drive (GB)'},{key:'driveInterface',label:'Interface',kind:'select',items:['SATA','NVMe']},{key:'driveSize',label:'Form factor',kind:'select',items:['2.5','3.5','M.2']},{key:'m2Length',label:'M.2 length (mm)'},{key:'powerW',label:'Power per drive (W)'}],
 'PSU':[{key:'capacityW',label:'Rated power (W)'},{key:'sataPower',label:'SATA power plugs'},{key:'formFactor',label:'PSU form factor',kind:'text'}],
 'Cooler':[{key:'heightMm',label:'Height (mm)'},{key:'supportsSockets',label:'Supported sockets',kind:'list'},{key:'powerW',label:'Power (W)'}]
};
const cardFields:typeof specFields['GPU']=[{key:'slotBus',label:'Slot bus',kind:'select',items:['PCI','PCIe']},{key:'slotWidth',label:'Physical connector width (x)'},{key:'requiredLanes',label:'Required electrical lanes'},{key:'minGeneration',label:'Minimum PCIe generation'},{key:'bracketWidth',label:'Rear bracket positions used'},{key:'lengthMm',label:'Length (mm)'},{key:'heightMm',label:'Height (mm)'},{key:'widthMm',label:'Width (mm)'},{key:'powerW',label:'Estimated power (W)'}];
const currentFields=computed(()=>{if(!componentDraft.value)return [];const c=componentDraft.value.category;return [...(specFields[c].length?specFields[c]:cardFields),...(c==='Network card'?[{key:'ethernet' as const,label:'Ethernet ports added'}]:[]),...(c==='Storage adapter'?[{key:'sledDrives' as const,label:'NVMe drive positions'},{key:'requiresBifurcation' as const,label:'Requires lane bifurcation',kind:'bool' as const},{key:'sledHotSwap' as const,label:'Vendor supports live hot-swap',kind:'bool' as const}]:[])];});
function specValue(key:keyof Specs){const v=componentDraft.value?.specs[key];return Array.isArray(v)?v.join(', '):v;}
function specText(key:keyof Specs){const v=specValue(key);return v===undefined?undefined:String(v);}
function setSpec(key:keyof Specs,value:unknown,kind?:string){if(!componentDraft.value)return;const specs=componentDraft.value.specs as Record<string,unknown>;if(value===''||value===null||value===undefined){delete specs[key];return;}specs[key]=kind==='list'?String(value).split(',').map(v=>v.trim()).filter(Boolean).map(v=>key==='m2Lengths'?Number(v):v):kind==='bool'?!!value:kind==='text'||kind==='select'?String(value):Number(value);}
function editComponent(c?:Component){componentDraft.value=c?clone(c):{id:uid(),name:'',category:'Scientific card',manufacturer:'',specs:{},source:'',verified:false};advanced.value=false;jsonSpecs.value=JSON.stringify(componentDraft.value.specs,null,2);}
function changeCategory(){if(componentDraft.value)componentDraft.value.specs={};advanced.value=false;}
function toggleAdvanced(){if(!componentDraft.value)return;if(!advanced.value)jsonSpecs.value=JSON.stringify(componentDraft.value.specs,null,2);else {try{componentDraft.value.specs=JSON.parse(jsonSpecs.value);}catch{return toast('Specifications must be valid JSON.');}}advanced.value=!advanced.value;}
async function saveComponent(){if(!componentDraft.value)return;try{if(advanced.value)componentDraft.value.specs=JSON.parse(jsonSpecs.value);if(await saveRecord('components',componentDraft.value)){componentDraft.value=null;toast('Component saved.');}}catch(e){toast(String(e));}}
function addSlot(){if(componentDraft.value){const s=componentDraft.value.specs;(s.slots??=[]).push({id:`SLOT_${s.slots.length+1}`,bus:'PCIe',physical:16,lanes:4,generation:3,position:s.slots.length+1});}}
function editSystem(s?:System){systemDraft.value=s?clone(s):{id:uid(),name:'',location:'',description:'',connections:[]};}
function addConnection(){systemDraft.value?.connections.push({id:uid(),name:'',usbA:0,usbC:0,ethernet:0,notes:''});}
async function saveSystem(){if(systemDraft.value&&await saveRecord('systems',systemDraft.value)){systemDraft.value=null;toast('Equipment system saved.');}}
function editPC(p?:InventoryPC){pcDraft.value=p?clone(p):{id:uid(),name:'',serial:'',location:'',configurationId:'',notes:''};}
async function savePC(){if(pcDraft.value&&await saveRecord('pcs',pcDraft.value)){pcDraft.value=null;toast('PC saved.');}}
async function deleteRecord(){if(!confirmDelete.value)return;busy.value=true;try{await api(`/api/${confirmDelete.value.collection}/${confirmDelete.value.id}`,{method:'DELETE'});await load();if(working.value?.id===confirmDelete.value.id)working.value=null;confirmDelete.value=null;toast('Record deleted.');}catch(e){toast(String(e));}finally{busy.value=false;}}
async function importCSV(){if(!importFile.value)return;importing.value=true;try{const result=await api(`/api/${csvCollection.value}/import`,{method:'POST',body:JSON.stringify({csv:await importFile.value.text()})});await load();toast(`Imported ${result.imported} records. Matching IDs updated.`);importFile.value=null;}catch(e){toast(String(e));}finally{importing.value=false;}}
onMounted(async()=>{await load();const context=(document as Document&{modelContext?:{registerTool:(t:unknown)=>Promise<void>}}).modelContext;if(context){for(const tool of [{name:'list_configurations',description:'Read saved PC configurations and compatibility summaries.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>db.value.configurations.map(c=>({id:c.id,name:c.name,status:reports.value[c.id].status}))},{name:'check_configuration',description:'Read compatibility findings for a saved configuration.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:{id:string})=>{const c=db.value.configurations.find(c=>c.id===input.id);if(!c)throw Error('Unknown configuration');return checkConfiguration(c,db.value);}}])try{await context.registerTool(tool);}catch{ /* Optional browser API. */ }}});
</script>

<template>
 <v-app>
  <aside class="sidebar">
   <a class="brand" href="#" @click.prevent="navigate('Configurations')"><span class="brand-mark">b<span>.</span></span><span>bench<span class="brand-period">.</span></span></a>
   <div class="workspace-name"><span class="workspace-avatar">LW</span><div>Lab workspace<small>Configuration management</small></div><v-icon :icon="mdiCogOutline" size="17" /></div>
   <div class="nav-label">WORKBENCH</div>
   <nav aria-label="Main navigation"><button v-for="item in navigation" :key="item.name" :class="['nav-item',{active:page===item.name}]" @click="navigate(item.name)"><v-icon :icon="item.icon" size="20" />{{item.name}}<span v-if="item.name==='Configurations'" class="nav-count">{{db.configurations.length}}</span></button></nav>
   <div class="side-note"><span class="tiny-dot" /> BUILT FOR THE BENCH<p>Every part.<br>One connected system.</p><div class="mini-chip"><v-icon :icon="mdiCheckCircleOutline" size="14" /> Local-first workspace</div></div>
   <button class="nav-item data-nav" :class="{active:page==='Data & imports'}" @click="navigate('Data & imports')"><v-icon :icon="mdiDatabaseOutline" size="20" />Data & imports</button>
   <div class="sidebar-footer"><span class="status-dot" /> CSV storage<span>v0.1</span></div>
  </aside>
  <main class="main">
   <header class="topbar"><div>Workspace <v-icon :icon="mdiChevronRight" size="15" /> <span>{{page}}</span><template v-if="working"><v-icon :icon="mdiChevronRight" size="15" /><span>{{working.name}}</span></template></div><div class="local-status"><span class="status-dot" />Local workspace<v-divider vertical class="mx-4" /><span class="user-avatar">LW</span></div></header>
   <div v-if="loading" class="loading-state"><v-progress-circular indeterminate color="primary" /><p>Opening your workbench…</p></div>
   <div v-else-if="failure" class="page-content"><v-alert type="error" title="Cannot connect to the local server">{{failure}}<br>Start the app with pnpm dev or pnpm start.</v-alert><v-btn class="mt-4" @click="load">Retry</v-btn></div>
   <div v-else class="page-content">
    <template v-if="working">
     <div class="detail-back"><button @click="navigate('Configurations')"><v-icon :icon="mdiArrowLeft" size="16" />All configurations</button><span>{{dirty?'Unsaved changes':'Saved to CSV'}}</span></div>
     <div class="page-heading"><div><div class="eyebrow">CONFIGURATION BUILDER</div><h1>{{working.name}}</h1><p>Build the PC around the system it needs to run.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiContentCopy" @click="duplicate(working)">Duplicate</v-btn><v-btn color="primary" :prepend-icon="mdiCheck" :loading="busy" @click="saveConfig">Save configuration</v-btn></div></div>
     <section class="builder-meta panel"><v-text-field v-model="working.name" label="Configuration name" /><v-select v-model="working.systemId" label="Equipment system" :items="[{title:'No equipment linked',value:''},...db.systems.map(s=>({title:s.name,value:s.id}))]" /><v-select v-model="working.status" label="Workflow status" :items="['Draft','In review','Approved']" /><v-text-field v-model="working.description" label="Description" class="meta-description" /></section>
     <div class="builder-grid"><div class="builder-main">
      <v-tabs v-model="detailTab" color="primary" class="content-tabs"><v-tab value="components">Components <span class="tab-count">{{working.placements.length}}</span></v-tab><v-tab value="connections">Connections</v-tab><v-tab value="storage">Storage plan</v-tab><v-tab value="checks">Compatibility</v-tab></v-tabs>
      <section v-if="detailTab==='components'" class="panel builder-section"><div class="section-head"><div><h2>Bill of materials</h2><p>Quantities are individual modules, cards or drives.</p></div><span class="neutral-badge">{{quantity(working)}} parts</span></div>
       <div class="add-component"><v-select v-model="addCategory" label="Category" :items="categories" @update:model-value="addPart=''" /><v-select v-model="addPart" label="Choose a component" :items="availableParts.map(c=>({title:c.name,value:c.id}))" /><v-text-field v-model.number="addQty" label="Qty" type="number" min="1" max="32" /><v-btn color="primary" :icon="mdiPlus" aria-label="Add component" :disabled="!addPart||!Number.isInteger(addQty)||addQty<1||addQty>32" @click="addComponent" /></div>
       <div v-if="!working.placements.length" class="empty-state"><v-icon :icon="mdiCubeOutline" size="34" /><h3>Your build starts here</h3><p>Add a chassis, motherboard, CPU and components.</p></div>
       <div v-for="p in working.placements" :key="p.id" class="bom-row"><span class="part-icon"><v-icon :icon="part(p.componentId)?.category==='Drive'?mdiHarddisk:mdiMemory" size="22" /></span><div class="bom-name"><small>{{part(p.componentId)?.category}}</small><strong>{{part(p.componentId)?.name||'Missing component'}}</strong><span>{{part(p.componentId)?summary(part(p.componentId)!):p.componentId}}</span></div><v-text-field v-model.number="p.quantity" label="Qty" type="number" min="1" max="32" class="qty-input" /><v-btn variant="text" :icon="mdiClose" size="small" aria-label="Remove component from build" @click="removePlacement(p.id)" /></div>
       <div v-if="selectedCards.length" class="slot-section"><h3>Expansion slot assignments</h3><p>Auto allocation checks bus, lanes and adjacent brackets. Choose a slot to reserve it.</p><div v-for="p in selectedCards" :key="p.id" class="slot-assignment"><span>{{part(p.componentId)?.name}}</span><v-select v-model="p.slotId" :items="[{title:'Auto-assign',value:''},...slots.map(s=>({title:`${s.id} · ${s.bus} x${s.physical} / ${s.lanes} lanes`,value:s.id}))]" label="Reserved slot" /><small>{{report?.slotAssignments[`${p.id}:0`]||'Unallocated'}}</small></div></div>
      </section>
      <section v-if="detailTab==='connections'" class="panel builder-section"><div class="section-head"><div><h2>Equipment connections</h2><p>{{linkedSystem?.description||'Choose an equipment system above to check required ports.'}}</p></div><v-btn v-if="linkedSystem" variant="outlined" size="small" @click="editSystem(linkedSystem)">Edit system</v-btn></div><template v-if="linkedSystem"><div class="port-summary"><div v-for="key in (['usbA','usbC','ethernet'] as const)" :key="key"><strong>{{portTotal(linkedSystem,key)}}</strong><span>{{{usbA:'USB-A required',usbC:'USB-C required',ethernet:'Ethernet required'}[key]}}</span></div></div><div v-for="connection in linkedSystem.connections" :key="connection.id" class="connection-row"><v-icon :icon="mdiLan" /><div><strong>{{connection.name}}</strong><p>{{connection.notes||'No additional requirements recorded.'}}</p></div><span>{{connection.usbA}} USB-A · {{connection.usbC}} USB-C · {{connection.ethernet}} Ethernet</span></div><div class="info-callout"><v-icon :icon="mdiInformationOutline" size="19" />Counts cover dedicated physical connections. Verify protocol, bandwidth, power, speed and isolation for each device.</div></template></section>
      <section v-if="detailTab==='storage'" class="panel builder-section"><div class="section-head"><div><h2>Storage & serviceability</h2><p>Separate boot and data, then plan access and redundancy.</p></div></div><div class="storage-options"><v-select v-model="working.storage.raid" label="Data redundancy" :items="[{title:'Independent drives',value:'none'},{title:'Mirror · 2 drives',value:'mirror'},{title:'RAID 5 · 3+ drives',value:'raid5'},{title:'RAID 6 · 4+ drives',value:'raid6'},{title:'RAID 10 · even, 4+ drives',value:'raid10'}]" /><v-switch v-model="working.storage.bootMirror" label="Mirror boot drive pair" color="primary" hide-details /></div><div class="storage-capacities"><div><small>BOOT CAPACITY</small><strong>{{capacity(report?.bootGb||0)}}</strong></div><div><small>USABLE DATA CAPACITY</small><strong>{{capacity(report?.usableDataGb||0)}}</strong></div></div><div v-if="!selectedDrives.length" class="empty-state"><h3>No drives selected</h3><p>Add drives in the Components tab to begin your plan.</p></div><div v-for="p in selectedDrives" :key="p.id" class="drive-row"><div><strong>{{part(p.componentId)?.name}}</strong><small>{{p.quantity}} × {{capacity(part(p.componentId)?.specs.capacityGb||0)}}</small></div><v-select v-model="p.role" label="Drive role" :items="['boot','data','general']" /><v-select v-model="p.mount" label="Mount / access" :items="[{title:'Automatic / onboard',value:'auto'},{title:'Internal bay',value:'internal'},{title:'Front hot-swap bay',value:'front-hot-swap'},{title:'Rear PCIe NVMe sled',value:'rear-sled'}]" /></div><div class="info-callout"><v-icon :icon="mdiInformationOutline" size="19" />Capacity uses decimal GB/TB before filesystem overhead. All data drives form one redundancy group. Rear NVMe sleds require a selected adapter and may require bifurcation; hot-swap is vendor dependent.</div></section>
      <section v-if="detailTab==='checks'" class="panel builder-section"><div class="section-head"><div><h2>Compatibility report</h2><p>Checks update as you edit. Resolve conflicts and verify the review items.</p></div></div><div v-for="(f,i) in report?.findings" :key="i" :class="['finding',f.severity]"><v-icon :icon="f.severity==='pass'?mdiCheckCircleOutline:mdiAlertCircleOutline" size="20" /><div><strong>{{f.title}}</strong><p>{{f.detail}}</p></div><span>{{f.severity==='error'?'Conflict':f.severity==='warning'?'Review':'Pass'}}</span></div></section>
      <section class="panel build-notes"><h3>Build notes</h3><v-textarea v-model="working.notes" label="Installation, drivers, verification and commissioning notes" rows="3" /></section>
     </div><aside class="build-summary"><section class="panel"><div class="summary-title"><v-icon :icon="mdiCheckCircleOutline" size="20" /><h3>Build health</h3></div><span :class="['health-badge',report?.status==='Conflicts'?'conflict':'review']">{{report?.status}}</span><p>{{report?.findings.filter(f=>f.severity==='error').length}} conflicts · {{report?.findings.filter(f=>f.severity==='warning').length}} review items</p><v-btn variant="text" color="primary" :append-icon="mdiArrowRight" class="report-link" @click="detailTab='checks'">View full report</v-btn><v-divider class="my-4" /><h4>Capacity overview</h4><div v-for="r in report?.resources" :key="r.name" class="resource"><div><span>{{r.name}}</span><strong :class="{over:r.used>r.available}">{{r.used}} / {{r.available}}{{r.unit}}</strong></div><v-progress-linear :model-value="r.available?Math.min(100,r.used/r.available*100):r.used?100:0" :color="r.used>r.available?'error':'primary'" height="4" rounded /></div><div class="summary-foot">Planning checks are based on catalog specifications. Review manufacturer documentation before purchasing or installing.</div></section><v-btn variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'configurations',id:working.id,name:working.name}">Delete configuration</v-btn></aside></div>
    </template>

    <template v-else-if="page==='Configurations'">
     <div class="page-heading"><div><div class="eyebrow">YOUR HARDWARE, IN HARMONY</div><h1>Configurations</h1><p>A home for every build. A clear path from parts to purpose.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div>
     <div class="overview-grid"><div class="stat-card"><div><span>Total configurations</span><v-icon :icon="mdiDesktopTowerMonitor" size="19" /></div><strong>{{db.configurations.length.toString().padStart(2,'0')}}</strong><small>Designed for your equipment</small></div><div class="stat-card"><div><span>Components in catalog</span><v-icon :icon="mdiMemory" size="19" /></div><strong>{{db.components.length.toString().padStart(2,'0')}}</strong><small>From chassis to scientific cards</small></div><div class="stat-card"><div><span>Connected systems</span><v-icon :icon="mdiLan" size="19" /></div><strong>{{db.systems.length.toString().padStart(2,'0')}}</strong><small>Equipment requirements mapped</small></div><div class="stat-card attention"><div><span>Needs attention</span><v-icon :icon="mdiAlertCircleOutline" size="19" /></div><strong>{{conflictCount.toString().padStart(2,'0')}}</strong><small>Builds with compatibility conflicts</small></div></div>
     <section class="workspace-banner"><div class="banner-illustration"><div class="tower tower-one"><i /><i /><i /><span /></div><div class="tower tower-two"><i /><i /><span /></div><div class="connection-line" /></div><div><span class="eyebrow">FROM A PC TO A COMPLETE SYSTEM</span><h2>Build with the whole bench in mind.</h2><p>Check fit, expansion slots, instrument connections and storage<br class="desktop-break"> before a single component reaches the lab.</p></div><button @click="navigate('Equipment systems')">Explore equipment systems <v-icon :icon="mdiArrowTopRight" size="18" /></button></section>
     <div class="list-toolbar"><div class="toolbar-tabs"><button :class="{selected:filter==='All configurations'}" @click="filter='All configurations'">All configurations <span>{{db.configurations.length}}</span></button><button :class="{selected:filter==='Draft'}" @click="filter='Draft'">Drafts</button><button :class="{selected:filter==='In review'}" @click="filter='In review'">In review</button><button :class="{selected:filter==='Conflicts'}" @click="filter='Conflicts'">Conflicts</button></div><v-text-field v-model="search" placeholder="Search configurations…" :prepend-inner-icon="mdiMagnify" aria-label="Search configurations" hide-details class="search-input" /></div>
     <div class="config-grid"><article v-for="c in configs" :key="c.id" class="config-card"><div class="config-card-top"><span class="config-icon"><v-icon :icon="mdiDesktopTowerMonitor" size="24" /></span><span :class="['workflow-badge',c.status==='In review'?'in-review':c.status==='Approved'?'approved':'']"><span />{{c.status}}</span></div><button class="card-title" @click="openConfig(c)">{{c.name}}<v-icon :icon="mdiArrowTopRight" size="19" /></button><p class="card-description">{{c.description}}</p><div class="system-label"><v-icon :icon="mdiLan" size="16" />{{systemName(c.systemId)}}</div><div class="card-facts"><div><small>COMPONENTS</small><strong>{{quantity(c)}} <span>parts</span></strong></div><div><small>DATA STORAGE</small><strong>{{capacity(reports[c.id]?.usableDataGb||0)}}</strong></div></div><div :class="['card-health',errors(c.id)?'has-conflicts':'']"><v-icon :icon="errors(c.id)?mdiAlertCircleOutline:mdiCheckCircleOutline" size="17" /><span>{{errors(c.id)?`${errors(c.id)} compatibility conflicts`:'No conflicts · review required'}}</span></div><div class="card-footer"><span>Updated {{new Date(c.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}}</span><button @click="openConfig(c)">Open build <v-icon :icon="mdiArrowRight" size="16" /></button></div></article><button class="new-build-card" @click="newConfig"><span><v-icon :icon="mdiPlus" size="26" /></span><h3>Your next configuration</h3><p>Start with a purpose.<br>Find the right parts.</p><strong>Create a new build <v-icon :icon="mdiArrowRight" size="16" /></strong></button></div>
     <div v-if="!configs.length" class="empty-state"><h3>No configurations found</h3><p>Try a different search or create your first build.</p></div>
     <div class="bottom-note"><v-icon :icon="mdiInformationOutline" size="16" />Example workspace included. Verify or replace illustrative specifications before using a build.</div>
    </template>

    <template v-else-if="page==='Component catalog'">
     <div class="page-heading"><div><div class="eyebrow">THE PARTS THAT MAKE IT POSSIBLE</div><h1>Component catalog</h1><p>Dimensions, interfaces and capacity. Every detail in one place.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/export/components">Export CSV</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" @click="editComponent()">Add component</v-btn></div></div>
     <div class="catalog-toolbar"><v-text-field v-model="search" placeholder="Search parts or manufacturers…" :prepend-inner-icon="mdiMagnify" aria-label="Search components" hide-details /><v-select v-model="categoryFilter" :items="['All components',...categories]" label="Category" hide-details /><span>{{components.length}} components</span></div>
     <section class="panel table-panel"><v-table><thead><tr><th>COMPONENT</th><th>CATEGORY</th><th>SPECIFICATION SNAPSHOT</th><th>VERIFICATION</th><th></th></tr></thead><tbody><tr v-for="c in components" :key="c.id"><td><button class="table-name" @click="editComponent(c)">{{c.name}}</button><small>{{c.manufacturer||'Manufacturer not recorded'}}</small></td><td><span class="category-tag">{{c.category}}</span></td><td>{{summary(c)}}</td><td><span :class="['verification',c.verified?'verified':'']"><span />{{c.verified?'Verified':'Needs verification'}}</span></td><td><v-btn variant="text" :icon="mdiTrashCanOutline" size="small" aria-label="Delete component" @click="confirmDelete={collection:'components',id:c.id,name:c.name}" /></td></tr></tbody></v-table><div v-if="!components.length" class="empty-state"><h3>No matching components</h3><p>Add a component or adjust your filters.</p></div></section><div class="bottom-note"><v-icon :icon="mdiInformationOutline" size="16" />Blank specification fields mean unknown, not zero. Click a component to edit its dimensions, slots and connectors.</div>
    </template>

    <template v-else-if="page==='Equipment systems'">
     <div class="page-heading"><div><div class="eyebrow">BEYOND THE COMPUTER</div><h1>Equipment systems</h1><p>Define what each PC needs to connect to and control.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="editSystem()">Add equipment system</v-btn></div><v-text-field v-model="search" placeholder="Search equipment systems…" :prepend-inner-icon="mdiMagnify" aria-label="Search equipment systems" hide-details class="system-search" />
     <div class="systems-grid"><article v-for="s in systems" :key="s.id" class="panel system-card"><div class="system-card-head"><span class="config-icon"><v-icon :icon="mdiLan" size="25" /></span><span class="neutral-badge">{{s.connections.length}} devices</span></div><h2>{{s.name}}</h2><small>{{s.location||'Location not recorded'}}</small><p>{{s.description}}</p><div class="port-summary"><div><strong>{{portTotal(s,'usbA')}}</strong><span>USB-A</span></div><div><strong>{{portTotal(s,'usbC')}}</strong><span>USB-C</span></div><div><strong>{{portTotal(s,'ethernet')}}</strong><span>Ethernet</span></div></div><div class="device-tags"><span v-for="connection in s.connections" :key="connection.id">{{connection.name}}</span></div><div class="card-footer"><span>{{db.configurations.filter(c=>c.systemId===s.id).length}} linked builds</span><button @click="editSystem(s)">Edit requirements <v-icon :icon="mdiArrowRight" size="16" /></button></div></article></div><div v-if="!systems.length" class="empty-state"><h3>No equipment systems found</h3><p>Add equipment and its connection requirements.</p></div>
    </template>

    <template v-else-if="page==='PC inventory'">
     <div class="page-heading"><div><div class="eyebrow">FROM PLANNED TO INSTALLED</div><h1>PC inventory</h1><p>Track actual machines and the configurations they use.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="editPC()">Register PC</v-btn></div><v-text-field v-model="search" placeholder="Search names, serials or locations…" :prepend-inner-icon="mdiMagnify" aria-label="Search PCs" hide-details class="system-search" /><section class="panel table-panel"><v-table><thead><tr><th>PC / ASSET NAME</th><th>SERIAL NUMBER</th><th>LOCATION</th><th>CONFIGURATION</th><th></th></tr></thead><tbody><tr v-for="pc in pcs" :key="pc.id"><td><button class="table-name" @click="editPC(pc)">{{pc.name}}</button></td><td>{{pc.serial||'—'}}</td><td>{{pc.location||'—'}}</td><td>{{configName(pc.configurationId)}}</td><td><v-btn variant="text" :icon="mdiTrashCanOutline" size="small" aria-label="Delete PC" @click="confirmDelete={collection:'pcs',id:pc.id,name:pc.name}" /></td></tr></tbody></v-table><div v-if="!pcs.length" class="empty-state"><h3>No machines found</h3><p>Register a PC and link it to a build.</p></div></section><div class="info-callout mt-6"><v-icon :icon="mdiInformationOutline" />A PC inherits the components of its linked configuration. Duplicate the configuration for a machine with different installed parts.</div>
    </template>

    <template v-else-if="page==='Storage planner'">
     <div class="page-heading"><div><div class="eyebrow">CAPACITY MEETS CONTINUITY</div><h1>Storage planner</h1><p>Compare boot pairs, data redundancy and how each drive is serviced.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div><div class="storage-guide"><section class="panel"><v-icon :icon="mdiHarddisk" size="25" /><h3>Front hot-swap</h3><p>Serviceable SATA bays with a compatible backplane, power and hot-plug controller.</p></section><section class="panel"><v-icon :icon="mdiMemory" size="25" /><h3>Rear PCIe NVMe sled</h3><p>Consumes an expansion slot and lanes. May need bifurcation; live removal must be verified.</p></section><section class="panel"><v-icon :icon="mdiServerOutline" size="25" /><h3>Boot + data pairs</h3><p>Keep system and acquisition data separate. Plan mirrored pairs and independent backups.</p></section></div><section class="panel table-panel"><v-table><thead><tr><th>CONFIGURATION</th><th>BOOT</th><th>DATA LAYOUT</th><th>USABLE DATA</th><th>DRIVE LOCATIONS</th><th></th></tr></thead><tbody><tr v-for="c in db.configurations" :key="c.id"><td><button class="table-name" @click="openConfig(c);detailTab='storage'">{{c.name}}</button></td><td>{{c.storage.bootMirror?'Mirrored pair':'Independent'}}<small>{{capacity(reports[c.id].bootGb)}}</small></td><td>{{c.storage.raid==='none'?'Independent':c.storage.raid.toUpperCase()}}</td><td>{{capacity(reports[c.id].usableDataGb)}}</td><td><span v-for="mount in [...new Set(c.placements.filter(p=>part(p.componentId)?.category==='Drive').map(p=>p.mount))]" :key="mount" class="category-tag mr-1">{{mount}}</span></td><td><v-btn variant="text" :icon="mdiArrowTopRight" aria-label="Edit storage plan" @click="openConfig(c);detailTab='storage'" /></td></tr></tbody></v-table></section>
    </template>

    <template v-else-if="page==='Data & imports'">
     <div class="page-heading"><div><div class="eyebrow">YOUR WORK. YOUR DATA.</div><h1>Data & imports</h1><p>Portable CSV files, local persistence and a path for external parts.</p></div><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/backup">Download JSON backup</v-btn></div><div class="data-grid"><section class="panel data-section"><h2>Export your workspace</h2><p>Each collection is saved locally as CSV. Nested specifications and lists use JSON inside CSV cells.</p><a v-for="collection in ['components','systems','configurations','pcs']" :key="collection" :href="`/api/export/${collection}`" class="export-row"><v-icon :icon="mdiDatabaseOutline" size="20" /><div><strong>{{collection}}.csv</strong><small>Editable, round-trip compatible</small></div><v-icon :icon="mdiDownload" size="20" /></a></section><section class="panel data-section"><h2>Import CSV</h2><p>New IDs are added; matching IDs are updated. Invalid rows or broken references reject the whole import.</p><v-select v-model="csvCollection" label="Collection" :items="['components','systems','configurations','pcs']" class="mb-5" /><v-file-input v-model="importFile" label="Choose CSV file" accept=".csv,text/csv" variant="outlined" density="compact" /><v-btn color="primary" :prepend-icon="mdiUpload" :disabled="!importFile" :loading="importing" @click="importCSV">Validate & import</v-btn><small class="import-order">For workspace transfers, import components and systems before configurations, then PCs. Imports merge records; they do not remove absent records.</small></section></div><section class="panel source-section"><span class="config-icon"><v-icon :icon="mdiCubeOutline" size="25" /></span><div><h2>PCPartPicker page importer</h2><p>Convert locally saved PCPartPicker product HTML containing Product JSON-LD into a component CSV. The importer extracts name, brand and source; engineering specifications need manual verification.</p><code>pnpm import:pcpartpicker ./product.html --category CPU --output ./parts.csv</code><p class="source-note">No live database crawler is included. Saved pages without structured Product data will return a clear error. See the README for supported formats.</p></div></section>
    </template>
   </div>
  </main>

  <v-dialog :model-value="!!componentDraft" max-width="900" persistent @update:model-value="v=>!v&&(componentDraft=null)"><v-card v-if="componentDraft" class="editor-dialog"><div class="dialog-head"><div><span class="eyebrow">COMPONENT CATALOG</span><h2>{{db.components.some(c=>c.id===componentDraft?.id)?'Edit component':'Add component'}}</h2></div><v-btn :icon="mdiClose" variant="text" aria-label="Close component editor" @click="componentDraft=null" /></div><div class="dialog-body"><div class="form-grid"><v-text-field v-model="componentDraft.name" label="Component name *" /><v-select v-model="componentDraft.category" label="Category" :items="categories" @update:model-value="changeCategory" /><v-text-field v-model="componentDraft.manufacturer" label="Manufacturer" /><v-text-field v-model="componentDraft.source" label="Source / manufacturer documentation URL" /></div><div class="spec-heading"><h3>Engineering specifications</h3><v-btn variant="text" size="small" @click="toggleAdvanced">{{advanced?'Use form editor':'Edit JSON'}}</v-btn></div><p class="form-hint">Leave unknown values blank. Set known absent resources to 0. Example specifications are unverified.</p><v-textarea v-if="advanced" v-model="jsonSpecs" label="Specifications JSON" rows="15" class="json-editor" /><template v-else><div class="form-grid"><template v-for="field in currentFields" :key="field.key"><v-select v-if="field.kind==='select'" :model-value="specText(field.key)" :label="field.label" :items="field.items" clearable @update:model-value="v=>setSpec(field.key,v,field.kind)" /><v-switch v-else-if="field.kind==='bool'" :model-value="!!specValue(field.key)" :label="field.label" color="primary" hide-details @update:model-value="v=>setSpec(field.key,v,'bool')" /><v-text-field v-else :model-value="specValue(field.key)" :label="field.label" :type="field.kind?'text':'number'" :min="field.kind?undefined:0" @update:model-value="v=>setSpec(field.key,v,field.kind)" /></template></div><section v-if="componentDraft.category==='Motherboard'" class="slot-editor"><div class="spec-heading"><h3>Expansion slots</h3><v-btn :prepend-icon="mdiPlus" variant="outlined" size="small" @click="addSlot">Add slot</v-btn></div><p class="form-hint">Positions count from the first rear bracket. Enter electrical lanes separately from physical connector width.</p><div v-for="(slot,i) in componentDraft.specs.slots" :key="i" class="slot-form-row"><v-text-field v-model="slot.id" label="Slot ID" /><v-select v-model="slot.bus" label="Bus" :items="['PCI','PCIe']" /><v-text-field v-model.number="slot.physical" label="Width (x)" type="number" /><v-text-field v-model.number="slot.lanes" label="Lanes" type="number" /><v-text-field v-model.number="slot.generation" label="Gen" type="number" /><v-text-field v-model.number="slot.position" label="Position" type="number" /><v-btn :icon="mdiClose" variant="text" size="small" aria-label="Remove slot" @click="componentDraft.specs.slots?.splice(i,1)" /></div></section><v-textarea v-model="componentDraft.specs.notes" label="Specification notes / restrictions" rows="2" class="mt-6" /></template><v-checkbox v-model="componentDraft.verified" label="I have verified these specifications against manufacturer documentation" color="primary" hide-details /></div><div class="dialog-footer"><v-btn variant="text" @click="componentDraft=null">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!componentDraft.name.trim()" @click="saveComponent">Save component</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!systemDraft" max-width="950" persistent><v-card v-if="systemDraft" class="editor-dialog"><div class="dialog-head"><div><span class="eyebrow">EQUIPMENT REQUIREMENTS</span><h2>{{systemDraft.name||'New equipment system'}}</h2></div><v-btn variant="text" :icon="mdiClose" aria-label="Close system editor" @click="systemDraft=null" /></div><div class="dialog-body"><div class="form-grid"><v-text-field v-model="systemDraft.name" label="System name *" /><v-text-field v-model="systemDraft.location" label="Location" /></div><v-textarea v-model="systemDraft.description" label="What this system controls" rows="2" class="mt-5" /><div class="spec-heading"><h3>Devices & dedicated connections</h3><v-btn variant="outlined" :prepend-icon="mdiPlus" size="small" @click="addConnection">Add device</v-btn></div><div v-for="(connection,i) in systemDraft.connections" :key="connection.id" class="connection-form"><div class="connection-form-top"><v-text-field v-model="connection.name" label="Equipment name *" /><v-text-field v-model.number="connection.usbA" label="USB-A" type="number" min="0" /><v-text-field v-model.number="connection.usbC" label="USB-C" type="number" min="0" /><v-text-field v-model.number="connection.ethernet" label="Ethernet" type="number" min="0" /><v-btn variant="text" :icon="mdiClose" size="small" aria-label="Remove equipment" @click="systemDraft.connections.splice(i,1)" /></div><v-text-field v-model="connection.notes" label="Protocol, bandwidth, power, speed, isolation or driver requirements" /></div><v-btn v-if="db.systems.some(s=>s.id===systemDraft?.id)" variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'systems',id:systemDraft.id,name:systemDraft.name};systemDraft=null">Delete equipment system</v-btn></div><div class="dialog-footer"><v-btn variant="text" @click="systemDraft=null">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!systemDraft.name.trim()" @click="saveSystem">Save requirements</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!pcDraft" max-width="600" persistent><v-card v-if="pcDraft" class="editor-dialog"><div class="dialog-head"><h2>{{pcDraft.name||'Register PC'}}</h2><v-btn variant="text" :icon="mdiClose" aria-label="Close PC editor" @click="pcDraft=null" /></div><div class="dialog-body"><v-text-field v-model="pcDraft.name" label="PC / asset name *" class="mb-5" /><div class="form-grid"><v-text-field v-model="pcDraft.serial" label="Serial number" /><v-text-field v-model="pcDraft.location" label="Location" /></div><v-select v-model="pcDraft.configurationId" label="Installed configuration" :items="[{title:'Unassigned',value:''},...db.configurations.map(c=>({title:c.name,value:c.id}))]" class="my-5" /><v-textarea v-model="pcDraft.notes" label="Installation / asset notes" rows="3" /></div><div class="dialog-footer"><v-btn variant="text" @click="pcDraft=null">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!pcDraft.name.trim()" @click="savePC">Save PC</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!confirmDelete" max-width="440"><v-card class="editor-dialog"><div class="dialog-body"><h2>Delete {{confirmDelete?.name}}?</h2><p class="mt-4">This removes the record from the local CSV. Records referenced by other records cannot be deleted.</p></div><div class="dialog-footer"><v-btn variant="text" @click="confirmDelete=null">Cancel</v-btn><v-btn color="error" :loading="busy" @click="deleteRecord">Delete</v-btn></div></v-card></v-dialog>
  <v-snackbar v-model="noticeOpen" :timeout="6000" color="primary">{{notice}}<template #actions><v-btn variant="text" @click="noticeOpen=false">Close</v-btn></template></v-snackbar>
 </v-app>
</template>
